SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '15min';

-- Loose movements re-post when edited (docs/plan-separacion-fiscal-interno.md,
-- phase 4.6, PR E): an UPDATE of a column the entry reads compares the entry
-- with build_transaction_journal_lines at commit and re-posts only when they
-- differ (repost_journal, 20261031180534). Description, counterparty and notes
-- never fire it. A movement generated by a receipt, payment order, transfer or
-- invoice can no longer change its channel either.

create constraint trigger transactions_repost_journal
  after update of amount, transaction_date, accrual_month, account_id, channel_id, kind, cost_center_id
  on public.transactions
  deferrable initially deferred
  for each row execute function public.repost_journal_trigger();

create or replace function public.guard_transaction_immutable_when_linked()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (old.receipt_id is not null
      or old.payment_order_id is not null
      or old.transfer_pair_id is not null
      or old.invoice_id is not null)
     and (new.amount           is distinct from old.amount
       or new.transaction_date is distinct from old.transaction_date
       or new.accrual_month    is distinct from old.accrual_month
       or new.account_id       is distinct from old.account_id
       or new.kind             is distinct from old.kind
       or new.channel_id       is distinct from old.channel_id) then
    raise exception
      'No se puede editar monto, fecha, cuenta, tipo o canal de un movimiento generado por un recibo, orden de pago, transferencia o comprobante'
      using errcode = '55006', hint = 'jouve_guard';
  end if;
  return new;
end;
$$;

revoke all on function public.guard_transaction_immutable_when_linked() from public, anon, authenticated;
